<template>
  <div class="project-records"><header class="pr-head"><h2>记录与成果</h2><DewButton v-if="route.query.record" size="sm" type="ghost" @click="allRecords">查看全部记录</DewButton><DewButton v-if="project.can_write && !campView" size="sm" @click="open()">新增记录</DewButton></header><DewSkeleton v-if="loading" variant="rect" width="100%" height="160" /><p v-else-if="error" role="alert">{{ error }} <DewButton @click="load">重试</DewButton></p><template v-else><p v-if="!rows.length" class="pr-muted">{{ route.query.record?'当前记录不可访问或已不存在。':'暂无项目记录。' }}</p><p v-if="rows.length>=200" class="pr-muted">当前显示最近200条记录，历史日期也可在项目日历中查看。</p><article v-for="row in rows" :key="row.id" class="pr-record"><header><h3>{{ row.title }}</h3><DewTag size="sm">{{ kindText[row.kind] }} · {{ stateText[row.status] }}</DewTag></header><p class="pr-muted">{{ row.occurred_on }} · {{ row.author }}</p><p class="pr-content">{{ row.content }}</p><div class="pr-files"><DewButton v-for="file in row.files" :key="file.id" size="sm" type="ghost" @click="download(file)">{{ file.filename }}</DewButton></div><div class="pr-actions"><DewButton v-if="row.can_edit && project.can_write && !campView" size="sm" type="ghost" @click="open(row)">编辑记录</DewButton><template v-if="row.can_verify && !campView"><DewButton size="sm" @click="verify(row,'verified')">核验成果</DewButton><DewButton size="sm" type="ghost" @click="verify(row,'rejected')">退回成果</DewButton></template></div></article></template>
    <DewDialog v-model="dialog" :title="form.id ? '编辑项目记录' : '新增项目记录'" width="640px"><div class="pr-form"><label>记录类型<DewSelect v-model="form.kind" :disabled="!!form.id" :options="Object.entries(kindText).filter(([key])=>key!=='outcome'||project.can_manage).map(([value,label])=>({value,label}))" /></label><label>标题<DewInput v-model="form.title" placeholder="记录标题" /></label><label>实际日期<input v-model="form.occurred_on" type="date" :max="today" aria-label="记录实际日期"></label><label>记录内容<DewInput v-model="form.content" type="textarea" :rows="5" placeholder="记录过程、结论和下一步" /></label><label>本期共享范围<DewSelect v-model="form.binding_id" :options="[{value:'',label:'仅长期项目团队'},...bindings.filter(b=>b.status==='active').map(b=>({value:b.id,label:b.camp_name}))]" /></label><label>附件（合计48MB，最多20个）<input type="file" multiple @change="selectFiles"></label><p v-if="files.length" class="pr-muted">已选 {{ files.length }} 个附件</p><label>记录原因<DewInput v-model="form.reason" placeholder="说明本次新增或调整" /></label></div><template #footer><DewButton :loading="busy" :disabled="!form.title?.trim() || !form.reason?.trim()" @click="save">保存记录</DewButton></template></DewDialog>
  </div>
</template>
<script setup>
import {ref,reactive,watch,onBeforeUnmount} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {DewButton,DewTag,DewInput,DewSelect,DewDialog,DewSkeleton} from '@bme/dew-ui'
import {ElMessage,ElMessageBox} from 'element-plus'
import {projectService,mutation} from './service'
const props=defineProps({project:Object,binding:Object,campView:Boolean}),emit=defineEmits(['changed']),route=useRoute(),router=useRouter()
const rows=ref([]),bindings=ref([]),loading=ref(true),error=ref(''),dialog=ref(false),busy=ref(false),files=ref([]),form=reactive({}),context=ref(null)
const operationKey=ref(crypto.randomUUID())
const kindText={meeting:'项目组会',record:'研发记录',outcome:'项目成果'},stateText={published:'已记录',pending:'待核验',verified:'已核验',rejected:'待补充'}
const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai'}).format(new Date())
let sequence=0
async function load(){const seq=++sequence;loading.value=true;error.value='';rows.value=[];try{const d=await projectService.records(props.project.id,{binding:props.binding?.id,record_id:route.query.record||undefined,camp_view:props.campView?1:undefined});if(seq!==sequence)return;rows.value=d.records;context.value=d.project;if(!props.campView){const b=await projectService.camps(props.project.id);if(seq===sequence)bindings.value=b.bindings}}catch(e){if(seq===sequence)error.value=e.response?.data?.message||'记录加载失败'}finally{if(seq===sequence)loading.value=false}}
function allRecords(){const query={...route.query};delete query.record;router.push({query})}
function open(row){operationKey.value=crypto.randomUUID();Object.assign(form,{id:null,kind:'record',title:'',content:'',occurred_on:today,binding_id:'',reason:''},row||{});if(!form.binding_id)form.binding_id='';files.value=[];dialog.value=true}
function selectFiles(e){const selected=[...e.target.files];if(selected.length>20||selected.reduce((n,f)=>n+f.size,0)>48*1024*1024){ElMessage.warning('附件合计不能超过48MB，最多20个');e.target.value='';return}files.value=selected}
async function save(){if(busy.value)return;busy.value=true;try{await projectService.saveRecord(props.project.id,{...mutation(context.value||props.project,{kind:form.kind,title:form.title,content:form.content,occurred_on:form.occurred_on,binding_id:form.binding_id||null,reason:form.reason}),idempotency_key:operationKey.value},files.value,form.id);dialog.value=false;await load();emit('changed');ElMessage.success('记录已保存')}catch(e){ElMessage.error(e.response?.data?.message||'保存失败')}finally{busy.value=false}}
async function download(file){try{window.open(await projectService.fileUrl(file.id,props.binding?.id),'_blank','noopener')}catch(e){ElMessage.error(e.response?.data?.message||'附件不可访问')}}
async function verify(row,status){let reason;try{reason=(await ElMessageBox.prompt('填写核验依据','项目成果核验',{inputValidator:v=>!!v?.trim()||'请填写依据'})).value}catch{return}try{await projectService.verifyRecord(props.project.id,row.id,mutation(context.value||props.project,{status,reason}));await load();emit('changed')}catch(e){ElMessage.error(e.response?.data?.message||'核验失败')}}
watch(()=>[props.project.id,props.binding?.id,props.campView,route.query.record],()=>{dialog.value=false;bindings.value=[];load()},{immediate:true});onBeforeUnmount(()=>sequence++)
</script>
<style scoped>.pr-head,.pr-record header,.pr-actions,.pr-files{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.pr-record{padding:20px 0;border-bottom:1px solid var(--dew-card-flat-border)}.pr-record h3{margin:0;font-size:17px}.pr-content{white-space:pre-wrap;overflow-wrap:anywhere}.pr-muted{color:var(--dew-text-muted);font-size:12px}.pr-actions,.pr-files{justify-content:flex-start;margin-top:12px}.pr-form{display:flex;flex-direction:column;gap:15px}.pr-form label{display:flex;flex-direction:column;gap:7px;font-size:13px}.pr-form input{max-width:100%;font:inherit;color:var(--dew-text);background:var(--dew-card-flat-bg);border:1px solid var(--dew-card-flat-border);padding:8px;border-radius:8px}</style>
